        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            FILTER (
                tracker:id(?playlist) = %(playlist_id)s &&
                tracker:id(?entry) = %(entry_id)s
            )
        }
        '.replace('
', ' ').strip() % {'playlist_id': self.props.pl_id, 'entry_id': media.get_id()}
