def alloc(self, size, alignment):
    self.alignment = max(self.alignment, alignment)
    if size:
        misalign = self.stacksize % alignment
        if misalign:
            self.stacksize = self.stacksize - misalign + size
    l = StackLocation(self.stacksize, size)
    self.stacksize += size
    return l

def sanitize_snmp_table_columns(columns):
    endoids = []
    for (fetchoid, column) in columns:
        for (o, value) in column:
            endoid = extract_end_oid(fetchoid, o)
            if endoid not in endoids:
                endoids.append(endoid)
    endoids.sort(cmp=cmp_oids)
    new_columns = []
    for (fetchoid, column) in columns:
        current_endoids = [extract_end_oid(fetchoid, o) for (o, _) in column]
        if current_endoids != endoids:
            column.sort(cmp=cmp_oid_pairs)
        i = 0
        new_column = []
        for (o, value) in column:
            eo = extract_end_oid(fetchoid, o)
            if len(column) != len(endoids):
                while i < len(endoids) and endoids[i] != eo:
                    new_column.append('')
                    i += 1
            new_column.append(value)
            i += 1
        while i < len(endoids):
            new_column.append('')
            i += 1
        new_columns.append(new_column)
    return new_columns

def append(self, relpath, f, mode=None):
    abspath = self._abspath(relpath)
    fp = None
    try:
        try:
            fp = open(abspath, 'ab')
            if mode is not None:
                pass
        except (IOError, OSError) as e:
            self._translate_error(e, relpath)
        fp.seek(0, 2)
        result = fp.tell()
        self._pump(f, fp)
    finally:
        if fp is not None:
            fp.close()
    return result

def _name2(self, v, current_klass, attr_name):
    obj = v.name
    if obj in self.method_imported_globals:
        call_name = UU + self.modpfx() + obj + '.' + attr_name
    elif self.imported_classes.has_key(obj):
        attr_str = '.prototype.__class__.' + attr_name
        call_name = UU + self.imported_classes[obj] + '.__' + obj + attr_str
    elif obj in self.module_imports():
        call_name = obj + '.' + attr_name
    elif obj[0] == obj[0].upper():
        call_name = UU + self.modpfx() + '__' + obj + '.prototype.__class__.' + attr_name
    else:
        call_name = UU + self._name(v, current_klass) + '.' + attr_name
    return call_name

