def _hadoop_streaming_commands(self, step_num):
    version = self.get_hadoop_version()
    (mapper, bash_wrap_mapper) = self._render_substep(step_num, 'mapper')
    (combiner, bash_wrap_combiner) = self._render_substep(step_num, 'combiner')
    (reducer, bash_wrap_reducer) = self._render_substep(step_num, 'reducer')
    if combiner is not None and (not supports_combiners_in_hadoop_streaming(version)):
        bash_wrap_mapper = True
        mapper = '%s | sort | %s' % (mapper, combiner)
        combiner = None
        bash_wrap_combiner = False
    if bash_wrap_mapper:
        mapper = bash_wrap(mapper)
    if bash_wrap_combiner:
        combiner = bash_wrap(combiner)
    if bash_wrap_reducer:
        reducer = bash_wrap(reducer)
    return (mapper, combiner, reducer)

def ParseID3v1(string):
    from struct import error as StructError
    frames = {}
    try:
        (tag, title, artist, album, year, comment, track, genre) = unpack('3s30s30s30s4s29sbb', string)
    except StructError:
        return None
    if tag != 'TAG':
        return None
    title = title.strip('\x00').strip().decode('latin1')
    artist = artist.strip('\x00').strip().decode('latin1')
    album = album.strip('\x00').strip().decode('latin1')
    year = year.strip('\x00').strip().decode('latin1')
    comment = comment.strip('\x00').strip().decode('latin1')
    if title:
        frames['TIT2'] = TIT2(encoding=0, text=title)
    if artist:
        frames['TPE1'] = TPE1(encoding=0, text=[artist])
    if album:
        frames['TALB'] = TALB(encoding=0, text=album)
    if year:
        frames['TYER'] = TYER(encoding=0, text=year)
    if comment:
        frames['COMM'] = COMM(encoding=0, lang='eng', desc='ID3v1 Comment', text=comment)
    if track:
        frames['TRCK'] = TRCK(encoding=0, text=str(track))
    frames['TCON'] = TCON(encoding=0, text=str(genre))
    if version_requested == 2.4:
        frames['TDRC'] = TDRC(encoding=0, text=current_date)
    return frames

